function przedstawZFirma(firma, stanowisko) {
  return `${this.imie} z ${firma} na stanowisku ${stanowisko}`;
}

const pracownikTechCorp = przedstawZFirma.bind({ imie: "Ala" }, "TechCorp");
console.log(pracownikTechCorp("programistka")); // "Ala z TechCorp na stanowisku programistka"
console.log(pracownikTechCorp("liderka zespolu")); // "Ala z TechCorp na stanowisku liderka zespolu"

// call(thisArg, arg1, arg2, ...) - WYWOLUJE funkcje NATYCHMIAST,
//   argumenty podane osobno, po przecinku
// apply(thisArg, [arg1, arg2, ...]) - WYWOLUJE funkcje NATYCHMIAST,
//   argumenty podane jako JEDNA tablica
// bind(thisArg, arg1, arg2, ...) - NIE wywoluje funkcji od razu,
//   ZWRACA NOWA funkcje z na stale przypietym this (i opcjonalnie
//   czescia argumentow), ktora mozna wywolac PoZNIEJ, dowolna ilosc razy

class Zegarek {
  constructor(marka) {
    this.marka = marka;
    this.tykniecia = 0;
    this.tyknij = this.tyknij.bind(this);
  }
  tyknij() {
    this.tykniecia++;
  }
}

const zegarek = new Zegarek("Casio");
zegarek.tyknij();
console.log(zegarek.tykniecia); // 1

